import {Link} from '@primer/react'
import Pluralize from 'pluralize'
import {REPO_SELECTION, type RepoSelection} from './EstimateCostDialog/RepositorySelectionGroup'
import type {Cost} from '../types'
import {ALL_REPOS_REPO_COUNT} from '../constants'
import {CostSummaryBox} from './CostSummaryBox'

interface ReviewProps {
  additionalCost: string
  org: string
  cost: Cost
  repoSelection: RepoSelection
  selectedReposCount: number
  selectedLicenseCount: number
}

export function Review({
  additionalCost,
  org,
  cost,
  repoSelection,
  selectedReposCount,
  selectedLicenseCount,
}: ReviewProps) {
  const isSelectedRepos = repoSelection === REPO_SELECTION.SELECTED
  const {per_license: perLicenseCost, increased_license_usage: increasedLicenseUsage} = cost

  const licenseCount = isSelectedRepos ? selectedLicenseCount : increasedLicenseUsage
  const repositoryCount = isSelectedRepos ? selectedReposCount : ALL_REPOS_REPO_COUNT
  const repositoryCountText = isSelectedRepos ? Pluralize('repository', repositoryCount, true) : 'all repositories'
  const reposToEnableText = isSelectedRepos ? 'selected repositories' : 'all at risk repositories'

  return (
    <>
      <p>
        Would you like to enable Secret Protection with secret scanning alerts and push protection for{' '}
        {reposToEnableText}?
      </p>
      <CostSummaryBox
        additionalCost={additionalCost}
        licenseCount={licenseCount}
        repositoryCountText={repositoryCountText}
        perLicenseCost={perLicenseCost}
        variant="review"
      />
      <span className="fgColor-muted f-small lh-default">
        You will be charged for additional committers in your next billing cycle.{' '}
        <Link href={`/organizations/${org}/settings/billing`} inline>
          Review billing information
        </Link>{' '}
        for more details.
      </span>
    </>
  )
}

try{ Review.displayName ||= 'Review' } catch {}