import {type RepoSelection, RepositorySelectionGroup, REPO_SELECTION} from './RepositorySelectionGroup'
import type {Cost} from '../../types'
import Pluralize from 'pluralize'
import {ALL_REPOS_REPO_COUNT} from '../../constants'
import {CostSummaryBox} from '../CostSummaryBox'

interface CostEstimationProps {
  repoSelection: RepoSelection
  onRepoSelectionChange: (selection: RepoSelection) => void
  allReposAdditionalCost: string
  cost: Cost
  isEnterpriseOrMT?: boolean
}

export function CostEstimation({
  repoSelection,
  onRepoSelectionChange,
  allReposAdditionalCost,
  cost,
  isEnterpriseOrMT = false,
}: CostEstimationProps) {
  // When "Selected repositories" is chosen, show zero cost breakdown
  // When "All repositories" is chosen, show actual cost breakdown
  const isSelectedRepos = repoSelection === REPO_SELECTION.SELECTED
  const displayCost = isSelectedRepos ? '$0.00' : allReposAdditionalCost
  const {per_license: perLicenseCost, increased_license_usage: increasedLicenseUsage} = cost
  const licenseCount = isSelectedRepos ? 0 : increasedLicenseUsage
  const repositoryCount = isSelectedRepos ? 0 : ALL_REPOS_REPO_COUNT
  const repositoryCountText = isSelectedRepos ? Pluralize('repository', repositoryCount, true) : 'all repositories'

  return (
    <>
      <p>
        <span>Secret Protection is </span>
        {!isEnterpriseOrMT && <span>free for public repositories and </span>}
        <span>billed per active committer for private repositories.</span>
      </p>
      <p>Estimate your monthly cost based on selection.</p>

      <RepositorySelectionGroup value={repoSelection} onChange={onRepoSelectionChange} />

      <CostSummaryBox
        additionalCost={displayCost}
        licenseCount={licenseCount}
        repositoryCountText={repositoryCountText}
        perLicenseCost={perLicenseCost}
      />
    </>
  )
}

try{ CostEstimation.displayName ||= 'CostEstimation' } catch {}