import {useState} from 'react'
import {clsx} from 'clsx'
import {useQuery} from '@github-ui/react-query'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import useColorModes from '@github-ui/react-core/use-color-modes'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Button, Heading, Link} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {Accordion} from '@github-ui/accordion'

import {AssessmentResultPage} from '../components/AssessmentResultPage'
import type {Assessment, AssessmentSummary, Cost} from '../types'
import {queries, useCreateAssessmentMutation} from '../api'
import styles from './SecretRiskAssessmentPage.module.css'

export interface SecretRiskAssessmentPagePayload {
  help_url: string
  org: {
    login: string
    is_ghas_bundled: boolean
    is_ghas_metered: boolean
  }
  number?: number
  assessment?: Assessment | null
  assessmentList?: AssessmentSummary[] | null
  cost: Cost
  can_skip_rescan: boolean
  hawaii_exp_variant: number
  is_enterprise_or_mt: boolean
  show_enable_secret_protection_button: boolean
  display_previous_assessments: boolean
  show_roi_calculator?: boolean
  show_error_banner?: boolean
  show_enable_secret_protection_banner?: boolean
}

export function SecretRiskAssessmentPage({refetchInterval = 5000}: {refetchInterval?: number}) {
  // Guarantee `assessment` defaults to null (not undefined)
  // so `initialData` isn't considered unset and causes a query.
  const {
    help_url,
    org,
    number = null,
    assessment = null,
    assessmentList = null,
    cost,
    can_skip_rescan,
    hawaii_exp_variant,
    is_enterprise_or_mt,
    show_enable_secret_protection_button,
    display_previous_assessments,
    show_roi_calculator = false,
    show_error_banner = false,
    show_enable_secret_protection_banner = true,
  } = useRoutePayload<SecretRiskAssessmentPagePayload>()
  const {data, isError} = useQuery({
    ...queries.assessment(org.login, number),
    initialData: assessment,
    // Assessment is only gonna change if it's incomplete.
    staleTime: Infinity,
    refetchInterval: query => {
      // Don't poll for previous assessments cuz they're completed
      if (number !== null) return false
      // Stop polling if query fails 3 times.
      if (query.state.errorUpdateCount >= 3) {
        return false
      }
      const newAssessment = query.state.data
      if (!newAssessment || newAssessment?.is_complete) {
        return false
      }
      return refetchInterval
    },
  })

  if (!data || show_error_banner) {
    return (
      <LandingPage
        org={org.login}
        displayPreviousAssessments={display_previous_assessments}
        showErrorBanner={show_error_banner}
      />
    )
  }

  return (
    <>
      {isError && !data.is_complete && (
        <Banner
          className="mb-3"
          variant="critical"
          title="Error"
          description="Failed to update assessment progress. Please refresh the page, or try again later."
        />
      )}
      <AssessmentResultPage
        assessment={data}
        assessmentList={assessmentList}
        cost={cost}
        helpUrl={help_url}
        org={org.login}
        isGhasBundled={org.is_ghas_bundled}
        isGhasMetered={org.is_ghas_metered}
        canSkipRescan={can_skip_rescan}
        hawaiiExpVariant={hawaii_exp_variant}
        isEnterpriseOrMT={is_enterprise_or_mt}
        showEnableSecretProtectionButton={show_enable_secret_protection_button}
        displayPreviousAssessments={display_previous_assessments}
        currentAssessmentNumber={number ?? undefined}
        showROICalculator={show_roi_calculator}
        showEnableSecretProtectionBanner={show_enable_secret_protection_banner}
      />
    </>
  )
}

function LandingPage({
  org,
  displayPreviousAssessments = false,
  showErrorBanner = false,
}: {
  org: string
  displayPreviousAssessments?: boolean
  showErrorBanner?: boolean
}) {
  const mutation = useCreateAssessmentMutation({
    org,
    displayPreviousAssessments,
  })

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  return (
    <>
      {showErrorBanner && (
        <Banner
          className="mb-3"
          variant="critical"
          title="Error"
          description="Failed to load assessment data. Please refresh the page, or try again later."
        />
      )}
      {mutation.isError && (
        <Banner
          variant="critical"
          title="Error"
          description="Failed to scan your organization. Please try again later."
          className="mb-3"
        />
      )}

      <SecuritySecretLeaksPromoBanner
        className="mb-6 find-exposed-secrets"
        title="Find secrets exposed in your organization"
        description="Scan your organization now for free and receive a secret leaks audit with aggregate insights on any public leaks, leak sources, and token types."
        descriptionMaxWidth={400}
        primaryAction={{
          onClick: () => {
            mutation.mutate()
            sendClickAnalyticsEvent({
              location: 'security-assessment-pre-scan',
              category: 'find-secrets-banner',
              action: 'scan-organization',
              tag: 'button',
              group: 'expand',
            })
          },
          isPending: mutation.isPending,
          label: 'Scan your organization',
        }}
        secondaryAction={{
          href: 'https://gh.io/choosing-ghsp',
          onClick: () => {
            sendClickAnalyticsEvent({
              location: 'security-assessment-pre-scan',
              category: 'find-secrets-banner',
              action: 'learn-more',
              tag: 'button',
              group: 'expand',
            })
          },
          label: 'Learn More',
        }}
        images={{
          day: '/images/secret-scanning/risk-assessment/start_scan_banner--day.png',
          night: '/images/secret-scanning/risk-assessment/start_scan_banner--night.png',
        }}
        analyticsVisible={{
          category: 'find-secrets-banner',
          action: 'visible',
          group: 'expand',
          location: 'security-assessment-pre-scan',
        }}
      />
      <FAQ />
    </>
  )
}

function SecuritySecretLeaksPromoBanner({
  title,
  description,
  descriptionMaxWidth = 400,
  primaryAction,
  secondaryAction,
  images,
  analyticsVisible,
  className,
}: {
  title: string
  description: string
  descriptionMaxWidth?: number
  primaryAction: {onClick: () => void; label: string; isPending: boolean}
  secondaryAction: {onClick: () => void; label: string; href: string}
  images: {
    day: string
    night: string
  }
  analyticsVisible: Record<string, string>
  className?: string
}) {
  const colorModes = useColorModes()
  const color = colorModes.colorMode === 'auto' ? 'day' : colorModes.colorMode

  return (
    <div
      className={clsx('security-secret-leaks-promo-banner', className)}
      data-analytics-visible={JSON.stringify(analyticsVisible)}
    >
      <div className="security-secret-leaks-promo-banner-content">
        <h2 data-hpc className="h2 my-1">
          {title}
        </h2>

        <p className="color-fg-muted mb-0" style={{maxWidth: descriptionMaxWidth}}>
          {description}
        </p>

        <div className="security-secret-leaks-promo-banner-actions">
          <Button
            variant="primary"
            onClick={primaryAction.onClick}
            loading={primaryAction.isPending}
            className="d-inline-flex flex-items-center gap-1"
          >
            {primaryAction.label}
          </Button>
          <Link href={secondaryAction.href} onClick={secondaryAction.onClick}>
            {secondaryAction.label}
          </Link>
        </div>
      </div>

      <div className="security-secret-leaks-promo-banner-image-container">
        <img
          className="security-secret-leaks-promo-banner-image-el"
          src={images[color]}
          alt=""
          width={440}
          height={208}
        />
      </div>
    </div>
  )
}

