try{ SecretRiskAssessmentPage.displayName ||= 'SecretRiskAssessmentPage' } catch {}
try{ LandingPage.displayName ||= 'LandingPage' } catch {}
try{ SecuritySecretLeaksPromoBanner.displayName ||= 'SecuritySecretLeaksPromoBanner' } catch {}
try{ FAQ.displayName ||= 'FAQ' } catch {}